package android.content;import android.content.res.Resources;import android.graphics.drawable.Drawable;import android.view.inputmethod.InputMethodManager;public class Context{public Context getApplicationContext(){return this;}public ContentResolver getContentResolver(){return new ContentResolver();}public static final String INPUT_METHOD_SERVICE="input_method";public static final int MODE_PRIVATE=0;public static final java.util.Map<String,SharedPreferences> preferences=new java.util.HashMap<>();public SharedPreferences getSharedPreferences(String n,int mode){SharedPreferences p=preferences.get(n);if(p==null){p=new SharedPreferences();preferences.put(n,p);}return p;}public final android.content.pm.PackageManager manager=new android.content.pm.PackageManager();public android.content.pm.PackageManager getPackageManager(){return manager;}public final Resources resources=new Resources();public final InputMethodManager ime=new InputMethodManager();public Resources getResources(){return resources;}public String getPackageName(){return "com.hljzjx.edu.student.classroom";}public Object getSystemService(String name){return ime;}public Drawable getDrawable(int id){return new Drawable();}}